package cz.mh.rallye.rallye_backend.simulation.application;
import java.util.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.nio.charset.StandardCharsets;import java.io.ByteArrayInputStream;import java.security.*;import java.util.function.Supplier;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Value;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
import cz.mh.rallye.rallye_backend.competition.domain.*;import static cz.mh.rallye.rallye_backend.competition.domain.RaceEvaluator.*;
import cz.mh.rallye.rallye_backend.simulation.persistence.SimulationStore;import static cz.mh.rallye.rallye_backend.simulation.persistence.SimulationStore.*;
import cz.mh.rallye.rallye_backend.templates.application.*;import cz.mh.rallye.rallye_backend.templates.persistence.TemplateStore;import cz.mh.rallye.rallye_backend.races.application.EventFiles;
import cz.mh.rallye.rallye_backend.identity.application.AuthFailure;import cz.mh.rallye.rallye_backend.identity.application.AuthService.Principal;import cz.mh.rallye.rallye_backend.identity.persistence.*;import cz.mh.rallye.rallye_backend.shared.persistence.CommandStore;import cz.mh.rallye.rallye_backend.audit.application.AuditService;
@Service
public class SimulationService {
 public record Input(long version,UUID runId,UUID stageId,String code,Long deltaMs,String mode,Double latitude,Double longitude,Double accuracyMeters,Boolean mockLocation,Long throughSequence){@Override public String toString(){return "SimulationInput[redacted]";}}
 public record Created(UUID id,long version){}
 public record FileView(String fileName,String contentType,int byteSize,Integer width,Integer height,String url){}
 public record Content(String fileName,String contentType,byte[] bytes,boolean markdown,boolean pdf){}
 public record HistoricalPenalty(UUID id,UUID stageId,String cause,String points,boolean effectiveAtThisAction){}
 public record HistoryClock(Instant before,Instant after){}
 public record HistoryItem(UUID actionId,long sequence,String type,UUID stageId,Instant virtualAt,String outcome,String pointsDelta,List<HistoricalPenalty> penalties,ConfirmedInput input,GpsResult gps,Position position,HistoryClock clockChange){}
 public record HistoryPage(UUID simulationId,UUID runId,List<HistoryItem> items,boolean hasMore,long nextAfterSequence){}
 public static class NotReady extends RuntimeException {private final TemplateReadiness.Report report;public NotReady(TemplateReadiness.Report r){super("SIMULATION_TEMPLATE_NOT_READY");report=r;}public TemplateReadiness.Report report(){return report;}}
 private final SimulationStore store;private final TemplateStore templates;private final TemplateImageFiles source;private final SimulationFiles files;private final TemplateFileContent content;private final AdminStore roles;private final AccountStore accounts;private final CommandStore ledger;private final AuditService audit;private final Clock clock;private final TransactionTemplate tx;private final RaceEvaluator engine=new RaceEvaluator();
 public SimulationService(SimulationStore store,TemplateStore templates,TemplateImageFiles source,SimulationFiles files,EventFiles eventFiles,TemplateFileContent content,AdminStore roles,AccountStore accounts,CommandStore ledger,AuditService audit,Clock clock,PlatformTransactionManager manager){if(source.sameRoot(files.storage)||eventFiles.storage.sameRoot(files.storage))throw new IllegalArgumentException("Simulation storage must be separate");this.store=store;this.templates=templates;this.source=source;this.files=files;this.content=content;this.roles=roles;this.accounts=accounts;this.ledger=ledger;this.audit=audit;this.clock=clock;tx=new TransactionTemplate(manager);}
 private static Instant storedTime(Instant at){try{int year=at.atOffset(ZoneOffset.UTC).getYear();if(year< -4712||year>294276)throw error(422,"SIMULATION_TIME_OUT_OF_RANGE");return at;}catch(DateTimeException|ArithmeticException failure){throw error(422,"SIMULATION_TIME_OUT_OF_RANGE");}}
 private Instant now(){return clock.instant().truncatedTo(ChronoUnit.MILLIS);}
 private static AuthFailure error(int status,String code){return new AuthFailure(status,code);}
 public static <T>T rules(Supplier<T> task){try{return task.get();}catch(RuleViolation e){int status=switch(e.code()){case "SIMULATION_TIME_OUT_OF_RANGE","SIMULATION_POINTS_OVERFLOW"->422;case "INVALID_COORDINATES","INVALID_CODE_INPUT","AMBIGUOUS_COORDINATES","COORDINATE_SIGN_CONFLICT","MAP_URL_UNSUPPORTED"->400;default->409;};throw error(status,e.code());}}
 private void authorize(Principal actor){if(actor==null)throw AuthFailure.credentials();roles.lock();accounts.lockAccount(actor.accountId());if(!roles.activeVerified(actor.accountId())||!accounts.isActiveSession(actor.sessionId(),actor.accountId(),now()))throw AuthFailure.credentials();if(!roles.administrator(actor.accountId()))throw error(403,"ADMIN_REQUIRED");}
 private Session owned(Principal actor,UUID id,boolean expiry){var s=store.lock(id);if(s==null||!s.owner().equals(actor.accountId()))throw error(404,"SIMULATION_NOT_FOUND");if(s.engine()!=RaceEvaluator.VERSION||s.format()!=1)throw error(503,"SIMULATION_ENGINE_VERSION_UNSUPPORTED");return s;}
 private SimulationView.View view(Session s){return withoutExpiry(SimulationView.of(s,TemplateFileReferences.names(store.files(s.id()))));}

 private static Session changed(Session s,UUID run,long version,State state,Instant expires){return new Session(s.id(),s.owner(),s.templateId(),s.templateVersion(),s.templateName(),s.definition(),s.format(),s.engine(),run,version,state,s.createdAt(),expires);}
 public static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 public SimulationView.View create(Principal actor,UUID template,long templateVersion,UUID key,Instant virtualStart){if(template==null||key==null||templateVersion<0)throw error(400,"INVALID_REQUEST");Instant start=virtualStart==null?null:storedTime(virtualStart.truncatedTo(ChronoUnit.MILLIS));return rules(()->source.files.exclusive(()->files.storage.files.exclusive(()->{UUID id=UUID.randomUUID();var written=new ArrayList<String>();try{return tx.execute(status->{authorize(actor);String request=json(Arrays.asList(template,templateVersion,start==null?null:start.toString()));String old=ledger.replay(actor.accountId(),key,"SIMULATION_CREATE",request,now());if(old!=null){var result=read(old,Created.class);var found=owned(actor,result.id(),true);var root=store.firstRun(found.id());return view(changed(found,root.id(),0,root.initial(),null));}
  var t=templates.lock(template);if(t==null)throw error(404,"TEMPLATE_NOT_FOUND");if(t.version()!=templateVersion)throw error(409,"TEMPLATE_VERSION_CONFLICT");var stages=templates.stages(template);var library=templates.images(template);var report=TemplateFileReferences.readiness(t,stages,library);if(!Set.of("DRAFT","READY").contains(t.status())||!report.ready())throw new NotReady(report);
  var copied=new ArrayList<Stage>();for(var s:stages)copied.add(new Stage(UUID.randomUUID(),s.id(),s.sequenceNo(),s.name(),s.expectedDurationMs(),s.maxPenaltyPoints(),InstructionsMarkdown.copyToSimulation(template,id,s.instructionsMarkdown()),s.configuration()));var def=new Definition(t.skipPenaltyPoints(),t.defaultWrongCodePenaltyPoints(),copied);Instant at=now();var initial=engine.start(def,start==null?at:start);UUID run=UUID.randomUUID();store.insert(id,actor.accountId(),template,t.version(),t.name(),def,run,initial,at,null);store.run(run,id,null,null,initial);
  for(var file:library){byte[] bytes=source.read(template,file.fileName());if(bytes.length!=file.byteSize()||!ImageNames.key(file.fileName()).equals(file.nameKey()))throw error(503,"SIMULATION_SNAPSHOT_UNAVAILABLE");var v=content.validate(file.fileName(),new ByteArrayInputStream(bytes),source.files);if(!v.contentType().equals(file.contentType())||!Objects.equals(v.width(),file.width())||!Objects.equals(v.height(),file.height())||!Objects.equals(v.markdown(),file.markdownSource()))throw error(503,"SIMULATION_SNAPSHOT_UNAVAILABLE");String markdown=file.markdownSource();if(file.isMarkdown()){markdown=InstructionsMarkdown.copyToSimulation(template,id,markdown);bytes=markdown.getBytes(StandardCharsets.UTF_8);}files.storage.write(id,file.fileName(),bytes);written.add(file.fileName());store.file(UUID.randomUUID(),id,file.fileName(),file.nameKey(),new TemplateFileContent.Validated(bytes,file.contentType(),file.width(),file.height(),markdown),at);}
  audit.simulation(actor.accountId(),AuditService.Event.SIMULATION_CREATED,id);ledger.save(actor.accountId(),key,id,"SIMULATION_CREATE",request,json(new Created(id,0)),at);return view(owned(actor,id,true));});}catch(RuntimeException failure){for(String name:written)try{if(!store.referenced(id,name))files.storage.remove(id,name);}catch(RuntimeException uncertain){/* Keep possibly committed bytes; locked orphan cleanup retries. */}throw failure;}})));}
 public record StageSummary(UUID id,String name,int sequenceNo){}
 public record Summary(UUID id,SimulationView.Source source,Instant createdAt,Instant lastActivityAt,UUID runId,long version,String status,StageSummary currentStage){}
 public record Page(List<Summary> items,int page,int size,boolean hasMore){}
 public Page list(Principal actor,String status,int page,int size){
  if(page<0||page>10000||size<1||size>100||status!=null&&!Set.of("RUNNING","COMPLETED","CLOSED").contains(status))throw error(400,"INVALID_REQUEST");
  return tx.execute(s->{authorize(actor);var rows=store.list(actor.accountId(),status,page,size);
   return new Page(rows.stream().limit(size).map(r->new Summary(r.id(),new SimulationView.Source(r.templateId(),r.templateVersion(),r.templateName()),r.createdAt(),r.lastActivityAt(),r.runId(),r.version(),r.status(),r.stage()==null?null:new StageSummary(r.stage().id(),r.stage().name(),r.stage().sequenceNo()))).toList(),page,size,rows.size()>size);
  });
 }
 private static SimulationView.View withoutExpiry(SimulationView.View v){return new SimulationView.View(v.id(),v.runId(),v.version(),v.status(),v.source(),v.clock(),v.position(),v.gpsPreview(),v.currentStage(),v.dashboard(),null);}
 public SimulationView.View get(Principal actor,UUID id){return rules(()->tx.execute(s->{authorize(actor);return view(owned(actor,id,true));}));}
 public GpsParser.Coordinates parse(Principal actor,String text){return rules(()->tx.execute(s->{authorize(actor);return GpsParser.parse(text);}));}
 public SimulationView.View mutate(Principal actor,UUID id,UUID key,String operation,Input in){if(key==null||in==null||in.runId()==null||in.version()<0)throw error(400,"INVALID_REQUEST");return rules(()->tx.execute(status->{authorize(actor);var current=owned(actor,id,true);String canonicalCode=in.code();if(operation.equals("CODE")){try{canonicalCode=cz.mh.rallye.rallye_backend.templates.domain.StageConfiguration.normalizeCode(in.code());}catch(RuntimeException bad){throw error(400,"INVALID_CODE_INPUT");}}String fingerprint=hash(json(Arrays.asList(operation,id,in.version(),in.runId(),in.stageId(),canonicalCode,in.deltaMs(),in.mode(),in.latitude(),in.longitude(),in.accuracyMeters(),in.mockLocation(),in.throughSequence())));var old=store.replay(id,actor.accountId(),key);if(old!=null){if(!old.expiresAt().isAfter(now()))throw error(409,"IDEMPOTENCY_KEY_EXPIRED");if(!fingerprint.equals(old.fingerprint()))throw error(409,"IDEMPOTENCY_CONFLICT");return withoutExpiry(read(old.response(),SimulationView.View.class));}
  if(current.version()!=in.version())throw error(409,"SIMULATION_VERSION_CONFLICT");if(!current.runId().equals(in.runId()))throw error(409,"SIMULATION_RUN_CONFLICT");if(current.state().status().equals("CLOSED")&&!Set.of("RESTART","RESTORE","CLOSE").contains(operation))throw error(409,"SIMULATION_NOT_RUNNING");
  UUID action=UUID.randomUUID(),run=current.runId();long seq=store.nextSequence(id);State before=current.state(),after;boolean branch=false;
  switch(operation){
   case "CODE","GPS","SKIP","COMPLETE"->after=engine.evaluate(current.definition(),before,operation,in.stageId(),in.code(),action,seq);
   case "CLOCK_SHIFT"->after=engine.shift(before,in.deltaMs(),action,seq);
   case "POSITION"->after=engine.position(before,position(current,in),action,seq);
   case "CLOSE"->after=engine.close(before,action,seq);
   case "RESTART","RESTORE"->{branch=true;State point=operation.equals("RESTART")?engine.start(current.definition(),before.virtualStartAt()):stateAt(current,current.runId(),in.throughSequence());after=new State(point.virtualStartAt(),point.virtualNow(),point.timeFloor(),point.status(),point.position(),point.stages(),point.penalties(),new Action(action,seq,operation,null,operation.equals("RESTART")?"RESTARTED":"RESTORED",delta(total(point),total(before)),point.virtualNow(),null));run=UUID.randomUUID();store.run(run,id,operation.equals("RESTORE")?current.runId():null,operation.equals("RESTORE")?in.throughSequence():null,after);}
   default->throw error(400,"INVALID_REQUEST");
  }
  storedTime(after.virtualNow());boolean changed=!before.equals(after);long version=changed?Math.addExact(current.version(),1):current.version();Instant expires=null;var result=changed(current,run,version,after,expires);if(changed)store.update(id,run,version,after,now(),expires);
  if(changed&&Set.of("RESTART","RESTORE","CLOSE").contains(operation))audit.simulation(actor.accountId(),AuditService.Event.valueOf("SIMULATION_"+(operation.equals("RESTART")?"RESTARTED":operation.equals("RESTORE")?"RESTORED":"CLOSED")),id);
  var output=view(result);Action fact=after.lastAction()!=null&&after.lastAction().actionId().equals(action)?after.lastAction():new Action(action,seq,operation,in.stageId(),operation.equals("COMPLETE")?"STAGE_ALREADY_COMPLETED":"UNCHANGED",0,after.virtualNow(),null);var facts=new Facts(operation,fact,after.virtualNow(),after.position(),confirmed(operation,in),before.virtualNow());store.command(action,id,run,actor.accountId(),key,seq,operation,current.version(),fingerprint,facts,new Effect(hash(json(branch?after:before)),hash(json(after))),json(output),now());return output;
 }));}
 private static String integer(Long value){return value==null?null:value.toString();}
 private static ConfirmedInput confirmed(String operation,Input in){
  boolean position=operation.equals("POSITION");
  return new ConfirmedInput(Long.toString(in.version()),in.runId(),in.stageId(),operation.equals("CODE")?in.code():null,
    operation.equals("CLOCK_SHIFT")?integer(in.deltaMs()):null,position?in.mode():null,position?in.latitude():null,
    position?in.longitude():null,position?in.accuracyMeters():null,position?in.mockLocation():null,
    operation.equals("RESTORE")?integer(in.throughSequence()):null);
 }
 private Position position(Session session,Input in){return switch(in.mode()){
  case "INPUT"->new Position(in.latitude(),in.longitude(),in.accuracyMeters(),in.mockLocation());
  case "UNAVAILABLE"->null;
  case "TARGET","OUTSIDE"->{var p=current(session.state());if(p==null||!p.stageId().equals(in.stageId()))throw error(409,"STAGE_NOT_CURRENT");var c=session.definition().stages().stream().filter(s->s.id().equals(p.stageId())).findFirst().orElseThrow().configuration().gps();if(!c.enabled())throw error(409,"CHECK_NOT_ENABLED");yield in.mode().equals("TARGET")?new Position(c.latitude(),c.longitude(),0,false):GpsMath.outside(c.latitude(),c.longitude(),c.radiusMeters());}
  default->throw error(400,"INVALID_REQUEST");};}

 private State stateAt(Session session,UUID runId,long through){if(through<0)throw error(409,"SIMULATION_RESTORE_INVALID");var visited=new HashSet<UUID>();UUID id=runId;while(visited.add(id)){var run=store.run(session.id(),id);if(run==null)throw error(409,"SIMULATION_RESTORE_INVALID");if(through==0)return run.initial();var commands=store.commands(session.id(),id,through);if(commands.stream().noneMatch(c->c.sequence()==through)){if(run.parent()!=null&&through<=run.through()){id=run.parent();continue;}throw error(409,"SIMULATION_RESTORE_INVALID");}State state=run.initial();for(var command:commands){if(!hash(json(state)).equals(command.effect().beforeHash()))throw error(503,"SIMULATION_SNAPSHOT_UNAVAILABLE");state=replay(session.definition(),state,command);if(!hash(json(state)).equals(command.effect().afterHash()))throw error(503,"SIMULATION_SNAPSHOT_UNAVAILABLE");}return state;}throw error(503,"SIMULATION_SNAPSHOT_UNAVAILABLE");}
 private State replay(Definition def,State state,Command command){var f=command.facts();if(f.action()==null)return state;return switch(f.operation()){
  case "CLOCK_SHIFT"->engine.shift(state,Duration.between(state.virtualNow(),f.clock()).toMillis(),command.id(),command.sequence());
  case "POSITION"->engine.position(state,f.position(),command.id(),command.sequence());
  case "CLOSE"->engine.close(state,command.id(),command.sequence());
  case "RESTART","RESTORE"->state; // Initial state of the new branch already contains this control transition.
  default->engine.replay(def,state,f.action());};}
 public HistoryPage history(Principal actor,UUID id,UUID runId,long after,int size){if(runId==null||after<0||size<1||size>100)throw error(400,"INVALID_REQUEST");return rules(()->tx.execute(s->{authorize(actor);var session=owned(actor,id,true);var commands=new ArrayList<Command>();var seen=new HashSet<UUID>();UUID run=runId;long limit=Long.MAX_VALUE;while(run!=null){if(!seen.add(run))throw error(503,"SIMULATION_SNAPSHOT_UNAVAILABLE");var row=store.run(id,run);if(row==null)throw error(409,"SIMULATION_RESTORE_INVALID");commands.addAll(store.commands(id,run,limit));limit=row.through()==null?0:Math.min(limit,row.through());run=row.parent();}var selected=commands.stream().filter(c->c.sequence()>after).sorted(Comparator.comparingLong(Command::sequence)).limit(size+1L).toList();var items=new ArrayList<HistoryItem>();for(var c:selected.subList(0,Math.min(size,selected.size()))){var state=stateAt(session,c.runId(),c.sequence());var a=c.facts().action();items.add(new HistoryItem(c.id(),c.sequence(),c.operation(),a==null?null:a.stageId(),c.facts().clock(),a==null?"UNCHANGED":a.outcome(),a==null?"0":Long.toString(a.pointsDelta()),state.penalties().stream().filter(p->p.actionId().equals(c.id())).map(p->new HistoricalPenalty(p.id(),p.stageId(),p.cause(),Long.toString(p.points()),p.effective())).toList(),c.facts().input(),a==null?null:a.gps(),Set.of("POSITION","GPS").contains(c.operation())?c.facts().position():null,c.facts().previousClock()==null?null:new HistoryClock(c.facts().previousClock(),c.facts().clock())));}return new HistoryPage(id,runId,List.copyOf(items),selected.size()>size,items.isEmpty()?after:items.getLast().sequence());}));}
 public List<FileView> files(Principal actor,UUID id){return tx.execute(s->{authorize(actor);owned(actor,id,true);return store.files(id).stream().map(f->new FileView(f.fileName(),f.contentType(),f.byteSize(),f.width(),f.height(),ImageNames.simulationUrl(id,f.fileName()))).toList();});}
 public Content file(Principal actor,UUID id,String name){String key=ImageNames.key(name);return files.storage.files.exclusive(()->tx.execute(s->{authorize(actor);owned(actor,id,true);var library=store.files(id);var file=library.stream().filter(f->f.nameKey().equals(key)).findFirst().orElseThrow(()->error(404,"SIMULATION_FILE_NOT_FOUND"));byte[] bytes=files.storage.read(id,file.fileName());if(bytes.length!=file.byteSize())throw error(503,"SIMULATION_SNAPSHOT_UNAVAILABLE");if(file.isMarkdown()){if(!Arrays.equals(bytes,file.markdownSource().getBytes(StandardCharsets.UTF_8)))throw error(503,"SIMULATION_SNAPSHOT_UNAVAILABLE");bytes=TemplateDocumentHtml.page(file.fileName(),InstructionsMarkdown.renderSimulation(id,file.markdownSource(),TemplateFileReferences.names(library))).getBytes(StandardCharsets.UTF_8);}return new Content(file.fileName(),file.isMarkdown()?"text/html;charset=UTF-8":file.contentType(),bytes,file.isMarkdown(),file.contentType().equals("application/pdf"));}));}
 public void delete(Principal actor,UUID id,long version){if(version<0)throw error(400,"INVALID_REQUEST");files.storage.files.exclusive(()->{var removed=tx.execute(s->{authorize(actor);var session=owned(actor,id,false);if(session.version()!=version)throw error(409,"SIMULATION_VERSION_CONFLICT");var library=store.files(id);store.delete(id);audit.simulation(actor.accountId(),AuditService.Event.SIMULATION_DELETED,id);return library;});for(var f:removed)files.storage.remove(id,f.fileName());return null;});}
 /** Internal maintenance of replay responses and orphan files only; never expires simulations. */
 public int cleanup(){return files.storage.files.exclusive(()->{
  tx.executeWithoutResult(s->store.expireReplay(now()));
  return files.storage.cleanup(now().minusSeconds(86400),store::referenced);
 });}
}
